                    continue
                finish_time = start_time + desired_time[nsid]
                if finish_time > endmin[nsid]:
                    continue
                # Recurse
                dfs(nsid, finish_time, visited_mask | (1 << nidx), path+[nsid], value_accum + values[nsid])
        # Try starting from each site within their open window
        for sid in site_ids:
            sidx = site_idx_map[sid]
            start_minutes = beginmin[sid]
            finish_time = start_minutes + desired_time[sid]
